CommercialPartners PartnerUserActivityLogs::getCommercialPartners(const DbClientPtr &clientPtr) const {
    static const std::string sql = "select * from commercial_partners where id = $1";
    Result r(nullptr);
    {
        auto binder = *clientPtr << sql;
        binder << *partnerId_ << Mode::Blocking >>
            [&r](const Result &result) { r = result; };
        binder.exec();
    }
    if (r.size() == 0)
    {
        throw UnexpectedRows("0 rows found");
    }
    else if (r.size() > 1)
    {
        throw UnexpectedRows("Found more than one row");
    }
    return CommercialPartners(r[0]);
}

void PartnerUserActivityLogs::getCommercialPartners(const DbClientPtr &clientPtr,
                                                    const std::function<void(CommercialPartners)> &rcb,
                                                    const ExceptionCallback &ecb) const
{
    static const std::string sql = "select * from commercial_partners where id = $1";
    *clientPtr << sql
               << *partnerId_
               >> [rcb = std::move(rcb), ecb](const Result &r){
                    if (r.size() == 0)
                    {
                        ecb(UnexpectedRows("0 rows found"));
                    }
                    else if (r.size() > 1)
                    {
                        ecb(UnexpectedRows("Found more than one row"));
                    }
                    else
                    {
                        rcb(CommercialPartners(r[0]));
                    }
               }
               >> ecb;
}

